function applyCrop(){const p=selectedPhoto();if(!p||!crop)return false;snapshot();const r=crop,sx=p.sx+(r.x-p.x)/p.w*p.sw,sy=p.sy+(r.y-p.y)/p.h*p.sh,sw=r.w/p.w*p.sw,sh=r.h/p.h*p.sh;Object.assign(p,r,{sx,sy,sw,sh});setMode('size');notice('선택한 사진을 잘랐어요.');return true;}
