$('imageFile').onchange=async e=>{const files=Array.from(e.target.files);e.target.value='';if(!files.length)return;if(busy)return notice('사진을 불러오는 중입니다. 잠시 기다려 주세요.');if(state.photos.length+files.length>100)return notice('사진은 100장까지 추가할 수 있습니다.',true);busy=true;$('imageFile').disabled=true;const serial=generation;notice('사진을 불러오는 중이에요…');try{const loaded=[];for(const f of files)loaded.push(await cleanImage(f));if(serial!==generation)return;snapshot();for(const img of loaded){const p={id:crypto.randomUUID(),src:img.src,sx:0,sy:0,sw:img.width,sh:img.height,x:0,y:0,w:img.width,h:img.height};images.set(img.src,img);fitPhoto(p);state.photos.push(p);selectionId=p.id;}setMode('size');sync();frameRect(sceneRect(state));notice(`${loaded.length}장 추가했어요. 항목 목록에서 겹친 사진도 선택할 수 있습니다.`);}catch(err){notice(err.message+' 이번에 선택한 파일은 추가하지 않았으며 기존 작업은 유지됩니다.',true);}finally{busy=false;$('imageFile').disabled=false;}};
