$('format').onchange=()=>draw();
const presets=[{name:'빈 캔버스',sub:'YOUR OWN CANVAS',title:'직접 꾸미기',bg:'#ffffff',color:'#262633',design:'plain',text:'나만의 문구',ratio:'1:1'},{name:'차분한 순간',sub:'MOMENTS TO KEEP',title:'a little moment.',bg:'#e9e4db',color:'#ffffff',design:'quiet',text:'오늘의 작은 순간을\n오래 기억하기',ratio:'1:1'},{name:'나만의 한마디',sub:'YOUR WORDS, YOUR WAY',title:'MAKE IT YOURS.',bg:'#d9e9c2',color:'#334531',design:'bold',text:'지금, 나답게.',ratio:'4:5'},{name:'오늘의 기록',sub:'A NOTE TO MYSELF',title:'Dear, today',bg:'#f1e4d9',color:'#71614f',design:'note',text:'조금 느려도 괜찮아.\n오늘도 한 걸음.',ratio:'9:16'}];
for(const p of presets){const b=document.createElement('button');b.className='preset';b.innerHTML='<div class="preset-art"><small></small><span></span></div><div class="preset-name"><span></span><span>↗</span></div>';b.querySelector('.preset-art').style.background=p.bg;b.querySelector('.preset-art').style.color=p.color;b.querySelector('small').textContent=p.sub;b.querySelector('.preset-art span').textContent=p.title;b.querySelector('.preset-name span').textContent=p.name;b.onclick=()=>{
 const titles=templateTexts(p.design,p.ratio,()=>crypto.randomUUID());
 const remaining=state.texts.filter(t=>t.templateRole!=='title');
 let t=selectedText();if(!t||t.templateRole==='title')t=remaining.find(t=>t.templateRole==='body')||remaining[0];
 if(remaining.length+titles.length+(t?0:1)>103)return notice('템플릿 문구를 추가할 공간이 부족합니다. 문구를 일부 삭제하세요.',true);
 snapshot();state.background=p.bg;state.design=p.design;state.shading.enabled=false;
 if(!t){t=newText(crypto.randomUUID());remaining.push(t);}
 Object.assign(t,{text:p.text,textColor:p.color,fontSize:64,textX:50,textY:72,fontFamily:'gothic',templateRole:'body'});
 state.texts=[...titles,...remaining];state.editableTemplateText=true;selectionId=t.id;
 changeRatio(state,p.ratio);setMode('size');sync();frameOutput();notice('템플릿의 모든 글자를 선택해 수정하거나 삭제할 수 있어요.');
 };$('presets').append(b);}
const dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('moment-studio-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('templates',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('저장 공간을 열 수 없습니다. JSON으로 백업해 주세요.'));});
async function dbRead(){const db=await dbPromise;return new Promise((resolve,reject)=>{const req=db.transaction('templates').objectStore('templates').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function dbSave(list){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('templates','readwrite'),s=tx.objectStore('templates');s.clear();for(const t of list)s.put(t);tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(Error('저장 공간이 부족하거나 사용할 수 없습니다. 기존 템플릿은 유지됩니다.'));});}
async function commitTemplates(next){await dbSave(next);templates=next;renderTemplates();}
async function restore(s){if(!validState(s))throw Error('템플릿 내용이 올바르지 않습니다.');const next=migrate(s),serial=++generation,prepared=await decodeState(next);if(serial!==generation)return;snapshot();for(const [src,img]of prepared)images.set(src,img);state=next;selectionId=state.photos.at(-1)?.id||state.texts.at(-1)?.id||null;setMode('size');sync();frameRect(sceneRect(state));}
function renderTemplates(){$('templateCount').textContent=templates.length;$('templates').replaceChildren();if(!templates.length){const p=document.createElement('p');p.className='muted';p.textContent='나만의 템플릿을 저장해 보세요.';$('templates').append(p);}for(const t of templates){const row=document.createElement('div');row.className='template-row';const name=document.createElement('strong');name.textContent=t.name;row.append(name);for(const [label,action]of [['불러오기',async()=>{await restore(t.state);$('templateName').value=t.name;notice('사진·문구·배경 설정을 불러왔어요.');}],['현재 편집으로 수정',async()=>{if(!confirm(`“${t.name}”을 현재 편집 내용으로 바꿀까요?`))return;if(mode==='crop')applyCrop();const name=$('templateName').value.trim()||t.name;await commitTemplates(templates.map(x=>x.id===t.id?{...x,name,state:structuredClone(state)}:x));notice('템플릿을 수정했어요.');}],['삭제',async()=>{if(!confirm(`“${t.name}”을 삭제할까요?`))return;await commitTemplates(templates.filter(x=>x.id!==t.id));notice('템플릿을 삭제했어요.');}]]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>action().catch(e=>notice(e.message,true));row.append(b);}$('templates').append(row);}}
$('saveTemplate').onclick=async()=>{const name=$('templateName').value.trim();if(!name)return notice('템플릿 이름을 입력해 주세요.',true);if(templates.length>=100)return notice('최대 100개까지 저장할 수 있습니다.',true);if(mode==='crop')applyCrop();try{await commitTemplates([...templates,{id:crypto.randomUUID(),name,state:structuredClone(state)}]);notice('모든 사진·문구·배경 설정을 저장했어요. 새로고침 후에도 유지됩니다.');}catch(e){notice(e.message,true);}};
$('exportJSON').onclick=()=>download(new Blob([JSON.stringify({version:2,templates},null,2)],{type:'application/json'}),'moment-templates.json');
$('importJSON').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>50*1024*1024)throw Error('50MB 이하의 JSON만 가져올 수 있습니다.');let bundle;try{bundle=JSON.parse(await file.text());}catch{throw Error('JSON 문법이 손상되었습니다.');}const imported=validateBundle(bundle);for(const t of imported)await decodeState(t.state);const next=[...templates];for(const t of imported){const i=next.findIndex(x=>x.id===t.id);if(i>=0)next[i]=t;else next.push(t);}if(next.length>100)throw Error('합계 100개를 넘을 수 없습니다.');if(imported.some(t=>templates.some(x=>x.id===t.id))&&!confirm('같은 ID의 템플릿을 백업 내용으로 복원할까요?'))return;await commitTemplates(next);notice(`${imported.length}개 템플릿을 복원했어요.`);}catch(err){notice(err.message+' 기존 편집과 템플릿은 유지됩니다.',true);}};
try{templates=validateBundle({version:2,templates:await dbRead()});renderTemplates();}catch(e){notice(e.message,true);}
sync();frameOutput();document.fonts.ready.then(()=>draw());
